import React, { useState } from 'react';
import BarcodeScanner from './BarcodeScanner';

const MEAL_SLOTS = ['Breakfast', 'Lunch', 'Dinner', 'Snack'];
const UNITS = ['g', 'ml', 'dl', 'piece', 'cup', 'tbsp', 'tsp'];

const emptyIngredient = {
  name: '', calories: '', protein: '', carbs: '',
  fat: '', fiber: '', sugar: '', salt: '', unit: 'g',
};

const emptyLogEntry = {
  date: new Date().toISOString().split('T')[0],
  slot: 'Breakfast', ingredientId: null,
  name: '', amount: '', unit: 'g',
  calories: 0, protein: 0, carbs: 0, fat: 0,
};

function getTodayStr() {
  return new Date().toISOString().split('T')[0];
}

function formatDate(dateStr) {
  if (!dateStr) return '';
  return new Date(dateStr + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
}

function FoodLog({ ingredientLibrary, setIngredientLibrary }) {
  const [activeTab, setActiveTab] = useState('log');
  const [foodLog, setFoodLog] = useState([]);
  const [showIngredientModal, setShowIngredientModal] = useState(false);
  const [showLogModal, setShowLogModal] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);
  const [ingredientForm, setIngredientForm] = useState(emptyIngredient);
  const [logForm, setLogForm] = useState(emptyLogEntry);
  const [editingId, setEditingId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [logSearchQuery, setLogSearchQuery] = useState('');
  const [lookupLoading, setLookupLoading] = useState(false);
  const [lookupError, setLookupError] = useState('');
  const [showScanner, setShowScanner] = useState(false);
  const [scannerTarget, setScannerTarget] = useState(null);
  const [selectedDate, setSelectedDate] = useState(getTodayStr());

  const todayStr = getTodayStr();

  const filteredLibrary = (ingredientLibrary || []).filter(i =>
    i.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const dayLog = foodLog.filter(e => e.date === selectedDate);

  const dayTotals = dayLog.reduce((totals, entry) => {
    totals.calories += entry.calories || 0;
    totals.protein += entry.protein || 0;
    totals.carbs += entry.carbs || 0;
    totals.fat += entry.fat || 0;
    return totals;
  }, { calories: 0, protein: 0, carbs: 0, fat: 0 });

  function handleScanResult(product) {
    setShowScanner(false);
    const found = {
      name: product.name,
      calories: product.per100g.calories,
      protein: product.per100g.protein,
      carbs: product.per100g.carbs,
      fat: product.per100g.fat,
      fiber: product.per100g.fiber,
      sugar: product.per100g.sugar,
      salt: product.per100g.salt,
      unit: 'g',
    };
    if (scannerTarget === 'ingredient') {
      setIngredientForm(found);
    } else {
      setLogForm({ ...logForm, name: found.name, _found: found });
    }
  }
  function calcNutrition(ingredient, amount) {
    const factor = (parseFloat(amount) || 0) / 100;
    return {
      calories: Math.round((parseFloat(ingredient.calories) || 0) * factor),
      protein: Math.round((parseFloat(ingredient.protein) || 0) * factor * 10) / 10,
      carbs: Math.round((parseFloat(ingredient.carbs) || 0) * factor * 10) / 10,
      fat: Math.round((parseFloat(ingredient.fat) || 0) * factor * 10) / 10,
    };
  }

  async function lookupByName() {
    if (!logSearchQuery.trim() && !ingredientForm.name.trim()) return;
    const query = logSearchQuery || ingredientForm.name;
    setLookupLoading(true);
    setLookupError('');
    try {
      const res = await fetch(
        `https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(query)}&action=process&json=true&page_size=1`
      );
      const data = await res.json();
      if (data.products && data.products.length > 0) {
        const p = data.products[0];
        const n = p.nutriments || {};
        const found = {
          name: p.product_name || query,
          calories: Math.round(n['energy-kcal_100g'] || 0),
          protein: Math.round((n['proteins_100g'] || 0) * 10) / 10,
          carbs: Math.round((n['carbohydrates_100g'] || 0) * 10) / 10,
          fat: Math.round((n['fat_100g'] || 0) * 10) / 10,
          fiber: Math.round((n['fiber_100g'] || 0) * 10) / 10,
          sugar: Math.round((n['sugars_100g'] || 0) * 10) / 10,
          salt: Math.round((n['salt_100g'] || 0) * 10) / 10,
          unit: 'g',
        };
        if (showIngredientModal) {
          setIngredientForm(found);
        } else {
          setLogForm({ ...logForm, name: found.name, ingredientId: null, _found: found });
        }
        setLogSearchQuery('');
      } else {
        setLookupError('Product not found. Try a different name.');
      }
    } catch (e) {
      setLookupError('Could not connect to OpenFoodFacts.');
    }
    setLookupLoading(false);
  }

  function saveIngredient() {
    if (!ingredientForm.name.trim()) return;
    if (editingId) {
      setIngredientLibrary((ingredientLibrary || []).map(i => i.id === editingId ? { ...i, ...ingredientForm } : i));
    } else {
      setIngredientLibrary([...(ingredientLibrary || []), { ...ingredientForm, id: Date.now() }]);
    }
    setShowIngredientModal(false);
    setEditingId(null);
    setIngredientForm(emptyIngredient);
  }

  function deleteIngredient(id) {
    setIngredientLibrary((ingredientLibrary || []).filter(i => i.id !== id));
    setShowDeleteConfirm(null);
  }

  function addToLog(ingredient, amount) {
    const nutrition = calcNutrition(ingredient, amount);
    setFoodLog([...foodLog, {
      ...logForm,
      id: Date.now(),
      name: ingredient.name,
      ingredientId: ingredient.id,
      amount,
      unit: ingredient.unit || 'g',
      ...nutrition,
    }]);
    setShowLogModal(false);
    setLogForm(emptyLogEntry);
    setLogSearchQuery('');
  }

  function deleteLogEntry(id) {
    setFoodLog(foodLog.filter(e => e.id !== id));
    setShowDeleteConfirm(null);
  }

  return (
    <div>
      {/* Sub tabs */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
        {['log', 'library'].map(tab => (
          <button key={tab} onClick={() => setActiveTab(tab)} style={{
            padding: '6px 14px', borderRadius: '20px', border: '1px solid',
            borderColor: activeTab === tab ? 'var(--accent)' : 'var(--border)',
            backgroundColor: activeTab === tab ? 'var(--accent)' : 'transparent',
            color: activeTab === tab ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '12px', fontFamily: 'Jost, sans-serif', fontWeight: '500',
            letterSpacing: '0.05em', cursor: 'pointer', textTransform: 'uppercase',
          }}>{tab === 'log' ? 'Daily Log' : 'Ingredient Library'}</button>
        ))}
      </div>

      {/* DAILY LOG TAB */}
      {activeTab === 'log' && (
        <div>
          {/* Date selector */}
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '16px' }}>
            <button onClick={() => {
              const d = new Date(selectedDate + 'T00:00:00');
              d.setDate(d.getDate() - 1);
              setSelectedDate(d.toISOString().split('T')[0]);
            }} style={{ background: 'none', border: 'none', fontSize: '22px', color: 'var(--text-secondary)', cursor: 'pointer', padding: '4px 10px' }}>‹</button>
            <span style={{ fontSize: '14px', fontWeight: '500' }}>
              {selectedDate === todayStr ? 'Today' : formatDate(selectedDate)}
            </span>
            <button onClick={() => {
              const d = new Date(selectedDate + 'T00:00:00');
              d.setDate(d.getDate() + 1);
              setSelectedDate(d.toISOString().split('T')[0]);
            }} style={{ background: 'none', border: 'none', fontSize: '22px', color: 'var(--text-secondary)', cursor: 'pointer', padding: '4px 10px' }}>›</button>
          </div>

          {/* Daily totals */}
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '14px', marginBottom: '16px' }}>
            <p style={{ fontSize: '11px', letterSpacing: '0.08em', color: 'var(--text-secondary)', marginBottom: '10px' }}>DAILY TOTALS</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '8px', textAlign: 'center' }}>
              {[
                { label: 'kcal', value: Math.round(dayTotals.calories) },
                { label: 'protein', value: `${Math.round(dayTotals.protein * 10) / 10}g` },
                { label: 'carbs', value: `${Math.round(dayTotals.carbs * 10) / 10}g` },
                { label: 'fat', value: `${Math.round(dayTotals.fat * 10) / 10}g` },
              ].map(n => (
                <div key={n.label}>
                  <p style={{ fontSize: '16px', fontWeight: '600', color: 'var(--accent)' }}>{n.value}</p>
                  <p style={{ fontSize: '10px', color: 'var(--text-secondary)' }}>{n.label}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Meal slots */}
          {MEAL_SLOTS.map(slot => {
            const slotEntries = dayLog.filter(e => e.slot === slot);
            return (
              <div key={slot} style={{ marginBottom: '14px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '6px' }}>
                  <p style={{ fontSize: '11px', letterSpacing: '0.08em', color: 'var(--text-secondary)' }}>{slot.toUpperCase()}</p>
                  <button onClick={() => { setLogForm({ ...emptyLogEntry, date: selectedDate, slot }); setShowLogModal(true); }} style={{
                    background: 'none', border: 'none', color: 'var(--accent)',
                    fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
                  }}>+ Add</button>
                </div>
                {slotEntries.length === 0 ? (
                  <p style={{ fontSize: '13px', color: 'var(--text-secondary)', padding: '8px 0' }}>Nothing logged</p>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                    {slotEntries.map(entry => (
                      <div key={entry.id} style={{ backgroundColor: 'var(--white)', borderRadius: '10px', padding: '10px 14px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <div>
                          <p style={{ fontSize: '13px', fontWeight: '500' }}>{entry.name}</p>
                          <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{entry.amount}{entry.unit} · {entry.calories} kcal</p>
                        </div>
                        <button onClick={() => setShowDeleteConfirm({ type: 'log', id: entry.id })} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* INGREDIENT LIBRARY TAB */}
      {activeTab === 'library' && (
        <div>
          <input
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            placeholder="Search ingredients..."
            style={{ width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '16px', outline: 'none' }}
          />

          {filteredLibrary.length === 0 ? (
            <div style={{ textAlign: 'center', marginTop: '40px', color: 'var(--text-secondary)' }}>
              <p style={{ fontSize: '32px', marginBottom: '12px' }}>🥦</p>
              <p style={{ fontSize: '14px' }}>{(ingredientLibrary || []).length === 0 ? 'No ingredients saved yet' : 'No results'}</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              {filteredLibrary.map(ing => (
                <div key={ing.id} style={{ backgroundColor: 'var(--white)', borderRadius: '12px', padding: '14px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div onClick={() => { setIngredientForm({ name: ing.name, calories: ing.calories, protein: ing.protein, carbs: ing.carbs, fat: ing.fat, fiber: ing.fiber || '', sugar: ing.sugar || '', salt: ing.salt || '', unit: ing.unit || 'g' }); setEditingId(ing.id); setShowIngredientModal(true); }}>
                    <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '2px' }}>{ing.name}</p>
                    <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{ing.calories} kcal · {ing.protein}g protein · {ing.carbs}g carbs · {ing.fat}g fat per 100{ing.unit || 'g'}</p>
                  </div>
                  <button onClick={() => setShowDeleteConfirm({ type: 'ingredient', id: ing.id })} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                </div>
              ))}
            </div>
          )}

          <button onClick={() => { setIngredientForm(emptyIngredient); setEditingId(null); setShowIngredientModal(true); }} style={{
            position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
            width: '52px', height: '52px', borderRadius: '50%',
            backgroundColor: 'var(--accent)', color: 'var(--white)', fontSize: '26px',
            border: 'none', cursor: 'pointer', boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>+</button>
        </div>
      )}

      {/* Barcode scanner */}
      {showScanner && (
        <BarcodeScanner onResult={handleScanResult} onClose={() => setShowScanner(false)} />
      )}
      {/* Delete confirm */}
      {showDeleteConfirm && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Delete this?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>This cannot be undone.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={cancelBtnStyle}>Cancel</button>
              <button onClick={() => {
                if (showDeleteConfirm.type === 'ingredient') deleteIngredient(showDeleteConfirm.id);
                if (showDeleteConfirm.type === 'log') deleteLogEntry(showDeleteConfirm.id);
              }} style={deleteBtnStyle}>Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* Add ingredient modal */}
      {showIngredientModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>{editingId ? 'Edit Ingredient' : 'New Ingredient'}</h3>

            {/* Search OpenFoodFacts */}
            <label style={labelStyle}>SEARCH OPENFOODFACTS</label>
            <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
              <input
                value={logSearchQuery}
                onChange={e => setLogSearchQuery(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && lookupByName()}
                placeholder="Search by name..."
                style={{ flex: 1, padding: '10px 12px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '13px', color: 'var(--text-primary)', outline: 'none' }}
              />
              <button onClick={lookupByName} disabled={lookupLoading} style={{
                padding: '10px 14px', borderRadius: '10px', border: 'none',
                backgroundColor: 'var(--accent)', color: 'var(--white)',
                fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
              }}>{lookupLoading ? '...' : 'Search'}</button>
              <button onClick={() => { setScannerTarget('ingredient'); setShowScanner(true); }} style={{
                padding: '10px 14px', borderRadius: '10px', border: '1px solid var(--border)',
                backgroundColor: 'transparent', fontSize: '18px', cursor: 'pointer',
              }}>📷</button>
            </div>
            {lookupError && <p style={{ fontSize: '12px', color: 'var(--danger)', marginBottom: '12px' }}>{lookupError}</p>}

            <label style={labelStyle}>NAME</label>
            <input value={ingredientForm.name} onChange={e => setIngredientForm({ ...ingredientForm, name: e.target.value })} placeholder="e.g. Oats, Chicken breast" style={inputStyle} />

            <label style={labelStyle}>VALUES PER 100G</label>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '20px' }}>
              {[
                { key: 'calories', label: 'Calories (kcal)' },
                { key: 'protein', label: 'Protein (g)' },
                { key: 'carbs', label: 'Carbs (g)' },
                { key: 'fat', label: 'Fat (g)' },
                { key: 'fiber', label: 'Fiber (g)' },
                { key: 'sugar', label: 'Sugar (g)' },
                { key: 'salt', label: 'Salt (g)' },
              ].map(n => (
                <div key={n.key}>
                  <label style={{ ...labelStyle, marginBottom: '4px' }}>{n.label}</label>
                  <input
                    type="number"
                    value={ingredientForm[n.key] || ''}
                    onChange={e => setIngredientForm({ ...ingredientForm, [n.key]: e.target.value })}
                    placeholder="0"
                    style={{ width: '100%', padding: '10px 12px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '13px', color: 'var(--text-primary)', outline: 'none' }}
                  />
                </div>
              ))}
            </div>

            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => { setShowIngredientModal(false); setIngredientForm(emptyIngredient); setLogSearchQuery(''); }} style={cancelBtnStyle}>Cancel</button>
              <button onClick={saveIngredient} style={saveBtnStyle}>{editingId ? 'Save Changes' : 'Save Ingredient'}</button>
            </div>
          </div>
        </div>
      )}

      {/* Log food modal */}
      {showLogModal && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '90vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px', fontSize: '18px' }}>Log Food</h3>
            <p style={{ fontSize: '13px', color: 'var(--text-secondary)', marginBottom: '20px' }}>{logForm.slot}</p>

            {/* Search */}
            <label style={labelStyle}>SEARCH OPENFOODFACTS OR LIBRARY</label>
            <div style={{ display: 'flex', gap: '8px', marginBottom: '12px' }}>
              <input
                value={logSearchQuery}
                onChange={e => setLogSearchQuery(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && lookupByName()}
                placeholder="Search food..."
                style={{ flex: 1, padding: '10px 12px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '13px', outline: 'none' }}
              />
              <button onClick={lookupByName} disabled={lookupLoading} style={{
                padding: '10px 14px', borderRadius: '10px', border: 'none',
                backgroundColor: 'var(--accent)', color: 'var(--white)',
                fontFamily: 'Jost, sans-serif', fontSize: '12px', cursor: 'pointer',
              }}>{lookupLoading ? '...' : 'Search'}</button>
              <button onClick={() => { setScannerTarget('log'); setShowScanner(true); }} style={{
                padding: '10px 14px', borderRadius: '10px', border: '1px solid var(--border)',
                backgroundColor: 'transparent', fontSize: '18px', cursor: 'pointer',
              }}>📷</button>
            </div>
            {lookupError && <p style={{ fontSize: '12px', color: 'var(--danger)', marginBottom: '8px' }}>{lookupError}</p>}

            {/* From library */}
            {(ingredientLibrary || []).length > 0 && (
              <>
                <label style={labelStyle}>FROM YOUR LIBRARY</label>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginBottom: '16px', maxHeight: '180px', overflowY: 'auto' }}>
                  {(ingredientLibrary || []).filter(i => i.name.toLowerCase().includes(logSearchQuery.toLowerCase())).map(ing => (
                    <button key={ing.id} onClick={() => {
                      const amount = '100';
                      addToLog(ing, amount);
                    }} style={{
                      padding: '10px 14px', borderRadius: '10px', border: '1px solid var(--border)',
                      backgroundColor: 'var(--white)', textAlign: 'left', cursor: 'pointer',
                      fontFamily: 'Jost, sans-serif',
                    }}>
                      <p style={{ fontSize: '13px', fontWeight: '500', color: 'var(--text-primary)', marginBottom: '2px' }}>{ing.name}</p>
                      <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{ing.calories} kcal per 100{ing.unit || 'g'}</p>
                    </button>
                  ))}
                </div>
              </>
            )}

            {/* Manual entry */}
            {logForm._found && (
              <>
                <label style={labelStyle}>FOUND: {logForm._found.name}</label>
                <p style={{ fontSize: '11px', color: 'var(--accent)', marginBottom: '12px' }}>
                  {logForm._found.calories} kcal · {logForm._found.protein}g protein · {logForm._found.carbs}g carbs · {logForm._found.fat}g fat per 100g
                </p>
                <label style={labelStyle}>AMOUNT (g)</label>
                <input
                  type="number"
                  value={logForm.amount}
                  onChange={e => setLogForm({ ...logForm, amount: e.target.value })}
                  placeholder="e.g. 150"
                  style={inputStyle}
                />
                <button onClick={() => addToLog(logForm._found, logForm.amount)} style={{ ...saveBtnStyle, width: '100%', marginBottom: '12px' }}>
                  Add to log
                </button>
              </>
            )}

            <button onClick={() => { setShowLogModal(false); setLogForm(emptyLogEntry); setLogSearchQuery(''); }} style={{ ...cancelBtnStyle, width: '100%' }}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500' };
const inputStyle = { width: '100%', padding: '12px 14px', borderRadius: '10px', border: '1px solid var(--border)', backgroundColor: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', color: 'var(--text-primary)', marginBottom: '20px', outline: 'none' };
const cancelBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: '1px solid var(--border)', backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const saveBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };
const deleteBtnStyle = { flex: 1, padding: '14px', borderRadius: '12px', border: 'none', backgroundColor: 'var(--danger)', color: 'var(--white)', fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer' };

export default FoodLog;