import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useState, useEffect } from 'react';

function getTodayStr() {
  return new Date().toISOString().split('T')[0];
}

function getGreeting() {
  const hour = new Date().getHours();
  if (hour < 12) return 'Good morning';
  if (hour < 18) return 'Good afternoon';
  return 'Good evening';
}

function getDayName() {
  return new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
}

function getTodayIndex() {
  return (new Date().getDay() + 6) % 7;
}

const MEAL_SLOTS = ['Breakfast', 'Lunch', 'Dinner', 'Snack'];

function getWeekDates() {
  const today = new Date();
  const day = today.getDay();
  const monday = new Date(today);
  monday.setDate(today.getDate() - ((day + 6) % 7));
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    return d.toISOString().split('T')[0];
  });
}

function Home({ tasks, habits, transactions, mealPlanner, outfitPlanner, shifts, workouts, events, relations, settings }) {
  const navigate = useNavigate();
  const [weather, setWeather] = useState(null);

  useEffect(() => {
    fetch('https://api.open-meteo.com/v1/forecast?latitude=55.6761&longitude=12.5683&current=temperature_2m,weathercode,windspeed_10m&wind_speed_unit=ms')
      .then(r => r.json())
      .then(data => {
        const code = data.current.weathercode;
        const temp = Math.round(data.current.temperature_2m);
        const wind = Math.round(data.current.windspeed_10m);
        const icon =
          code === 0 ? '☀️' :
          code <= 2 ? '🌤️' :
          code <= 48 ? '☁️' :
          code <= 67 ? '🌧️' :
          code <= 77 ? '❄️' :
          code <= 82 ? '🌦️' :
          '⛈️';
        const desc =
          code === 0 ? 'Clear sky' :
          code <= 2 ? 'Partly cloudy' :
          code <= 48 ? 'Cloudy' :
          code <= 67 ? 'Rain' :
          code <= 77 ? 'Snow' :
          code <= 82 ? 'Showers' :
          'Thunderstorm';
        setWeather({ temp, wind, icon, desc });
      })
      .catch(() => {});
  }, []);
  const todayStr = getTodayStr();
  const todayIndex = getTodayIndex();
  const weekDates = getWeekDates();

  // Today's tasks — incomplete, due today or overdue
  const todayTasks = (tasks || []).filter(t => !t.completed && t.dueDate <= todayStr).slice(0, 3);
  const totalPending = (tasks || []).filter(t => !t.completed).length;

  // Habits — how many done today
  const totalHabits = (habits || []).length;
  const doneHabits = (habits || []).filter(h => h.logs && h.logs.includes(todayStr)).length;

  // Today's meals
  const todayMeals = MEAL_SLOTS.map(slot => {
    const key = `${weekDates[todayIndex]}_${slot}`;
    return { slot, meal: mealPlanner[key] || null };
  }).filter(m => m.meal !== null);

  // Today's outfit
  const todayOutfit = (outfitPlanner || {})[todayIndex] || [];
  // Today's work shift from standard schedule
  const DAYS_OF_WEEK = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const todayDayName = DAYS_OF_WEEK[new Date().getDay()];
  const standardScheduleSlots = [
    { day: 'Monday', start: '13:30', end: '17:30', type: 'FK' },
    { day: 'Tuesday', start: '13:30', end: '17:30', type: 'FK' },
    { day: 'Wednesday', start: '13:30', end: '21:30', type: 'FK' },
    { day: 'Thursday', start: '13:30', end: '21:30', type: 'FK' },
    { day: 'Friday', start: '13:30', end: '17:30', type: 'FK' },
  ];
  const todayStandardShift = standardScheduleSlots.find(s => s.day === todayDayName);
  const todayCustomShifts = (shifts || []).filter(s => s.date === todayStr);

  // This week's days
  const weekDayNames = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  // This month's finance
  const now = new Date();
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
  const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];
  const monthTx = (transactions || []).filter(t => t.date >= monthStart && t.date <= monthEnd);
  const monthIncome = monthTx.filter(t => t.type === 'income').reduce((s, t) => s + t.amount, 0);
  const monthExpense = monthTx.filter(t => t.type === 'expense').reduce((s, t) => s + t.amount, 0);
  const balance = monthIncome - monthExpense;

  function fmt(amount) {
    return new Intl.NumberFormat('da-DK', { style: 'currency', currency: 'DKK', maximumFractionDigits: 0 }).format(amount);
  }

  const priorityColor = { High: '#B85C5C', Medium: '#A0856C', Low: '#7A9E87' };

  return (
    <div style={{ padding: '48px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>

      {/* Greeting */}
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em', marginBottom: '4px' }}>
        {getDayName().toUpperCase()}
      </p>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '32px' }}>
        <h1 style={{ fontSize: '28px', fontWeight: '300' }}>
          {getGreeting()}, {settings?.name || 'Salma'}
        </h1>
        {weather && (
          <div style={{ textAlign: 'right', flexShrink: 0, marginLeft: '16px' }}>
            <p style={{ fontSize: '24px', lineHeight: 1 }}>{weather.icon}</p>
            <p style={{ fontSize: '16px', fontWeight: '500', color: 'var(--text-primary)' }}>{weather.temp}°C</p>
            <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{weather.desc}</p>
            <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>{weather.wind} m/s</p>
          </div>
        )}
      </div>

      {/* Week overview */}
      <div style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '12px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>THIS WEEK</p>
        </div>
        <div style={{ display: 'flex', gap: '4px' }}>
          {weekDates.map((date, i) => {
            const isToday = date === todayStr;
            const hasTasks = (tasks || []).some(t => t.dueDate === date && !t.completed);
            const hasShift = standardScheduleSlots.some(s => s.day === ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]);
            const hasEvent = (events || []).some(e => e.date === date);
            return (
              <div key={date} style={{
                flex: 1, borderRadius: '10px', padding: '8px 4px',
                backgroundColor: isToday ? 'var(--accent)' : 'var(--surface)',
                display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '4px',
              }}>
                <p style={{ fontSize: '10px', color: isToday ? 'var(--white)' : 'var(--text-secondary)', fontWeight: isToday ? '600' : '400' }}>{weekDayNames[i]}</p>
                <p style={{ fontSize: '12px', fontWeight: '600', color: isToday ? 'var(--white)' : 'var(--text-primary)' }}>{new Date(date + 'T00:00:00').getDate()}</p>
                <div style={{ display: 'flex', gap: '2px', flexWrap: 'wrap', justifyContent: 'center' }}>
                  {hasShift && <div style={{ width: '5px', height: '5px', borderRadius: '50%', backgroundColor: isToday ? 'rgba(255,255,255,0.7)' : '#7A8FA6' }} />}
                  {hasTasks && <div style={{ width: '5px', height: '5px', borderRadius: '50%', backgroundColor: isToday ? 'rgba(255,255,255,0.7)' : '#B85C5C' }} />}
                  {hasEvent && <div style={{ width: '5px', height: '5px', borderRadius: '50%', backgroundColor: isToday ? 'rgba(255,255,255,0.7)' : '#A0856C' }} />}
                </div>
              </div>
            );
          })}
        </div>
        <div style={{ display: 'flex', gap: '12px', marginTop: '10px' }}>
          {[{ color: '#7A8FA6', label: 'Work' }, { color: '#B85C5C', label: 'Task' }, { color: '#A0856C', label: 'Event' }].map(l => (
            <div key={l.label} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <div style={{ width: '6px', height: '6px', borderRadius: '50%', backgroundColor: l.color }} />
              <span style={{ fontSize: '10px', color: 'var(--text-secondary)' }}>{l.label}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Today's work shift */}
      {(todayStandardShift || todayCustomShifts.length > 0) && (
        <div onClick={() => navigate('/work')} style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '12px', cursor: 'pointer' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
            <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>WORK TODAY</p>
            <p style={{ fontSize: '11px', color: 'var(--accent)' }}>View →</p>
          </div>
          {todayStandardShift && (
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
              <p style={{ fontSize: '14px' }}>{todayStandardShift.type} · {todayStandardShift.start}–{todayStandardShift.end}</p>
              <span style={{ fontSize: '11px', padding: '2px 8px', borderRadius: '10px', backgroundColor: 'var(--surface)', color: 'var(--text-secondary)' }}>Standard</span>
            </div>
          )}
          {todayCustomShifts.map(shift => (
            <div key={shift.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '4px' }}>
              <p style={{ fontSize: '14px' }}>{shift.name || shift.type} · {shift.start}–{shift.end}</p>
              <span style={{ fontSize: '11px', padding: '2px 8px', borderRadius: '10px', backgroundColor: 'var(--accent)' + '22', color: 'var(--accent)' }}>Extra</span>
            </div>
          ))}
        </div>
      )}
      {/* Tasks card */}
      <div onClick={() => navigate('/tasks')} style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '12px', cursor: 'pointer' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>TASKS</p>
          <p style={{ fontSize: '11px', color: 'var(--accent)' }}>{totalPending} pending →</p>
        </div>
        {todayTasks.length === 0 ? (
          <p style={{ fontSize: '14px', color: 'var(--text-secondary)' }}>Nothing due today ✓</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {todayTasks.map(task => (
              <div key={task.id} style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: priorityColor[task.priority] || 'var(--border)', flexShrink: 0 }} />
                <p style={{ fontSize: '14px', flex: 1 }}>{task.title}</p>
                {task.dueDate < todayStr && (
                  <span style={{ fontSize: '10px', color: 'var(--danger)', fontWeight: '600' }}>OVERDUE</span>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Habits card */}
      <div onClick={() => navigate('/habits')} style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '12px', cursor: 'pointer' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>HABITS</p>
          <p style={{ fontSize: '11px', color: 'var(--accent)' }}>View all →</p>
        </div>
        {totalHabits === 0 ? (
          <p style={{ fontSize: '14px', color: 'var(--text-secondary)' }}>No habits added yet</p>
        ) : (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
              <p style={{ fontSize: '14px' }}>{doneHabits} of {totalHabits} done today</p>
              <p style={{ fontSize: '14px', fontWeight: '600', color: doneHabits === totalHabits ? '#7A9E87' : 'var(--accent)' }}>
                {totalHabits > 0 ? Math.round((doneHabits / totalHabits) * 100) : 0}%
              </p>
            </div>
            <div style={{ height: '6px', backgroundColor: 'var(--surface)', borderRadius: '3px' }}>
              <div style={{
                height: '100%', borderRadius: '3px', transition: 'width 0.3s',
                width: `${totalHabits > 0 ? (doneHabits / totalHabits) * 100 : 0}%`,
                backgroundColor: doneHabits === totalHabits ? '#7A9E87' : 'var(--accent)',
              }} />
            </div>
          </div>
        )}
      </div>

      {/* Finance card */}
      <div onClick={() => navigate('/finance')} style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '12px', cursor: 'pointer' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>FINANCE · THIS MONTH</p>
          <p style={{ fontSize: '11px', color: 'var(--accent)' }}>View all →</p>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '8px' }}>
          {[
            { label: 'Income', value: monthIncome, color: '#7A9E87' },
            { label: 'Spent', value: monthExpense, color: '#B85C5C' },
            { label: 'Balance', value: balance, color: balance >= 0 ? '#7A9E87' : '#B85C5C' },
          ].map(card => (
            <div key={card.label} style={{ textAlign: 'center' }}>
              <p style={{ fontSize: '13px', fontWeight: '600', color: card.color }}>{fmt(card.value)}</p>
              <p style={{ fontSize: '10px', color: 'var(--text-secondary)', letterSpacing: '0.05em' }}>{card.label.toUpperCase()}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Meals card */}
      <div onClick={() => navigate('/meals')} style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '12px', cursor: 'pointer' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>MEALS TODAY</p>
          <p style={{ fontSize: '11px', color: 'var(--accent)' }}>Plan →</p>
        </div>
        {todayMeals.length === 0 ? (
          <p style={{ fontSize: '14px', color: 'var(--text-secondary)' }}>No meals planned today</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
            {todayMeals.map(({ slot, meal }) => (
              <div key={slot} style={{ display: 'flex', justifyContent: 'space-between' }}>
                <p style={{ fontSize: '11px', color: 'var(--text-secondary)', width: '80px' }}>{slot.toUpperCase()}</p>
                <p style={{ fontSize: '13px', flex: 1 }}>{meal.title}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Outfit card */}
      <div onClick={() => navigate('/outfit')} style={{ backgroundColor: 'var(--white)', borderRadius: '16px', padding: '18px', marginBottom: '12px', cursor: 'pointer' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
          <p style={{ fontSize: '11px', letterSpacing: '0.1em', color: 'var(--text-secondary)' }}>OUTFIT TODAY</p>
          <p style={{ fontSize: '11px', color: 'var(--accent)' }}>Plan →</p>
        </div>
        {todayOutfit.length === 0 ? (
          <p style={{ fontSize: '14px', color: 'var(--text-secondary)' }}>No outfit planned today</p>
        ) : (
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            {todayOutfit.map(item => (
              <div key={item.id} style={{ display: 'flex', alignItems: 'center', gap: '6px', backgroundColor: 'var(--surface)', borderRadius: '20px', padding: '4px 10px' }}>
                <div style={{ width: '10px', height: '10px', borderRadius: '50%', backgroundColor: item.color, border: '1px solid var(--border)' }} />
                <p style={{ fontSize: '12px' }}>{item.name}</p>
              </div>
            ))}
          </div>
        )}
      </div>

    </div>
  );
}

export default Home;