import React, { useState } from 'react';

const MEAL_SLOTS = ['Breakfast', 'Lunch', 'Dinner', 'Snack'];
const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

function getWeekDates() {
  const today = new Date();
  const day = today.getDay();
  const monday = new Date(today);
  monday.setDate(today.getDate() - ((day + 6) % 7));
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    return d.toISOString().split('T')[0];
  });
}

function getTodayIndex() {
  const day = new Date().getDay();
  return (day + 6) % 7;
}

function WeeklyPlanner({ recipes, planner, setPlanner }) {
  const [selectedDay, setSelectedDay] = useState(getTodayIndex());
  const [showPicker, setShowPicker] = useState(null);
  const weekDates = getWeekDates();

  function assignMeal(dayIndex, slot, recipe) {
    const key = `${weekDates[dayIndex]}_${slot}`;
    setPlanner({ ...planner, [key]: recipe });
    setShowPicker(null);
  }

  function removeMeal(dayIndex, slot) {
    const key = `${weekDates[dayIndex]}_${slot}`;
    const updated = { ...planner };
    delete updated[key];
    setPlanner(updated);
  }

  function getMeal(dayIndex, slot) {
    const key = `${weekDates[dayIndex]}_${slot}`;
    return planner[key] || null;
  }

  function getDayCalories(dayIndex) {
    return MEAL_SLOTS.reduce((total, slot) => {
      const meal = getMeal(dayIndex, slot);
      if (!meal || !meal.ingredients) return total;
      const cals = meal.ingredients.reduce((s, ing) => {
        return s + (ing.per100g.calories * (parseFloat(ing.amount) || 0) / 100);
      }, 0);
      return total + Math.round(cals / (meal.servings || 1));
    }, 0);
  }

  const todayIndex = getTodayIndex();

  return (
    <div>
      {/* Day selector */}
      <div style={{ display: 'flex', gap: '6px', overflowX: 'auto', paddingBottom: '4px', marginBottom: '20px' }}>
        {DAYS.map((day, i) => {
          const isToday = i === todayIndex;
          const isSelected = i === selectedDay;
          const calories = getDayCalories(i);
          return (
            <button key={day} onClick={() => setSelectedDay(i)} style={{
              flexShrink: 0, padding: '8px 12px', borderRadius: '12px', border: '1.5px solid',
              borderColor: isSelected ? 'var(--accent)' : isToday ? 'var(--accent-light)' : 'var(--border)',
              backgroundColor: isSelected ? 'var(--accent)' : 'transparent',
              color: isSelected ? 'var(--white)' : isToday ? 'var(--accent)' : 'var(--text-secondary)',
              fontFamily: 'Jost, sans-serif', fontSize: '12px', fontWeight: isSelected ? '600' : '400',
              cursor: 'pointer', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '2px',
            }}>
              <span>{day.slice(0, 3)}</span>
              {calories > 0 && <span style={{ fontSize: '10px', opacity: 0.8 }}>{calories}</span>}
            </button>
          );
        })}
      </div>

      {/* Selected day header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
        <h3 style={{ fontSize: '18px', fontWeight: '400' }}>{DAYS[selectedDay]}</h3>
        {getDayCalories(selectedDay) > 0 && (
          <span style={{ fontSize: '13px', color: 'var(--accent)', fontWeight: '500' }}>
            {getDayCalories(selectedDay)} kcal total
          </span>
        )}
      </div>

      {/* Meal slots */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {MEAL_SLOTS.map(slot => {
          const meal = getMeal(selectedDay, slot);
          return (
            <div key={slot} style={{ backgroundColor: 'var(--white)', borderRadius: '14px', padding: '14px 16px' }}>
              <p style={{ fontSize: '11px', letterSpacing: '0.08em', color: 'var(--text-secondary)', marginBottom: '8px' }}>
                {slot.toUpperCase()}
              </p>
              {meal ? (
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '2px' }}>{meal.title}</p>
                    <p style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>
                      {Math.round(meal.ingredients.reduce((s, ing) => s + (ing.per100g.calories * (parseFloat(ing.amount) || 0) / 100), 0) / (meal.servings || 1))} kcal per serving
                    </p>
                  </div>
                  <div style={{ display: 'flex', gap: '8px' }}>
                    <button onClick={() => setShowPicker({ day: selectedDay, slot })} style={{ background: 'none', border: 'none', color: 'var(--text-secondary)', fontSize: '14px', cursor: 'pointer' }}>✎</button>
                    <button onClick={() => removeMeal(selectedDay, slot)} style={{ background: 'none', border: 'none', color: 'var(--border)', fontSize: '16px', cursor: 'pointer' }}>✕</button>
                  </div>
                </div>
              ) : (
                <button onClick={() => setShowPicker({ day: selectedDay, slot })} style={{
                  width: '100%', padding: '10px', borderRadius: '10px',
                  border: '1.5px dashed var(--border)', backgroundColor: 'transparent',
                  color: 'var(--text-secondary)', fontFamily: 'Jost, sans-serif',
                  fontSize: '13px', cursor: 'pointer',
                }}>+ Add {slot.toLowerCase()}</button>
              )}
            </div>
          );
        })}
      </div>

      {/* Recipe picker modal */}
      {showPicker && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200 }}>
          <div style={{ backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0', padding: '28px 24px', width: '100%', maxWidth: '390px', maxHeight: '70vh', overflowY: 'auto' }}>
            <h3 style={{ fontWeight: '500', marginBottom: '20px', fontSize: '16px' }}>
              Choose {showPicker.slot} for {DAYS[showPicker.day]}
            </h3>
            {recipes.length === 0 ? (
              <p style={{ color: 'var(--text-secondary)', fontSize: '14px', textAlign: 'center', padding: '20px 0' }}>
                No recipes yet — add some in the Recipes tab first
              </p>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                {recipes.map(recipe => (
                  <button key={recipe.id} onClick={() => assignMeal(showPicker.day, showPicker.slot, recipe)} style={{
                    padding: '14px 16px', borderRadius: '12px', border: '1px solid var(--border)',
                    backgroundColor: 'var(--white)', textAlign: 'left', cursor: 'pointer',
                    fontFamily: 'Jost, sans-serif',
                  }}>
                    <p style={{ fontSize: '14px', fontWeight: '500', marginBottom: '2px', color: 'var(--text-primary)' }}>{recipe.title}</p>
                    <p style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{recipe.ingredients.length} ingredients · {recipe.servings} servings</p>
                  </button>
                ))}
              </div>
            )}
            <button onClick={() => setShowPicker(null)} style={{
              width: '100%', padding: '14px', borderRadius: '12px', border: '1px solid var(--border)',
              backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif', fontSize: '14px',
              cursor: 'pointer', marginTop: '16px',
            }}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default WeeklyPlanner;