import React, { useState } from 'react';

const FREQUENCIES = ['Daily', 'Weekly', 'Monthly', 'Yearly'];
const DAYS = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];

const emptyForm = {
    title: '',
    frequency: 'Daily',
    color: '#A0856C',
    startDate: new Date().toISOString().split('T')[0],
  };

const COLORS = ['#A0856C', '#7A9E87', '#7A8FA6', '#B85C5C', '#9B7AB8', '#C4A035'];

function getWeekDates() {
  const today = new Date();
  const day = today.getDay();
  const monday = new Date(today);
  monday.setDate(today.getDate() - ((day + 6) % 7));
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(monday);
    d.setDate(monday.getDate() + i);
    return d.toISOString().split('T')[0];
  });
}

function getTodayStr() {
  return new Date().toISOString().split('T')[0];
}

function calcStreak(logs) {
  if (!logs || logs.length === 0) return { current: 0, best: 0 };
  const sorted = [...new Set(logs)].sort().reverse();
  let current = 0;
  let best = 0;
  let streak = 0;
  const today = getTodayStr();
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const yesterdayStr = yesterday.toISOString().split('T')[0];

  let checking = sorted[0] === today || sorted[0] === yesterdayStr ? sorted[0] : null;
  if (!checking) return { current: 0, best: sorted.length > 0 ? 1 : 0 };

  for (let i = 0; i < sorted.length; i++) {
    const expected = new Date(checking);
    expected.setDate(expected.getDate() - i);
    const expectedStr = expected.toISOString().split('T')[0];
    if (sorted[i] === expectedStr) {
      streak++;
      if (i === 0) current = streak;
    } else {
      break;
    }
  }
  current = streak;
  best = Math.max(...Array.from({ length: sorted.length }, (_, i) => i + 1).filter((_, i) => {
    return sorted[i] !== undefined;
  }));
  best = sorted.length;
  return { current, best };
}

function calcCompletionRate(logs, frequency) {
  if (!logs || logs.length === 0) return 0;
  const days = frequency === 'Daily' ? 7 : frequency === 'Weekly' ? 4 : frequency === 'Monthly' ? 3 : 1;
  const recent = logs.filter(d => {
    const diff = (new Date() - new Date(d)) / 86400000;
    return diff <= days;
  });
  return Math.min(100, Math.round((recent.length / days) * 100));
}

function Habits({ habits, setHabits }) {
  const [filter, setFilter] = useState('All');
  const [showStats, setShowStats] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState(emptyForm);
  const [editingId, setEditingId] = useState(null);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);

  const weekDates = getWeekDates();
  const todayStr = getTodayStr();

  const filtered = habits.filter(h =>
    filter === 'All' || h.frequency === filter
  );

  function openCreate() {
    setForm(emptyForm);
    setEditingId(null);
    setShowModal(true);
  }

  function openEdit(habit) {
    setForm({ title: habit.title, frequency: habit.frequency, color: habit.color });
    setEditingId(habit.id);
    setShowModal(true);
  }

  function saveHabit() {
    if (!form.title.trim()) return;
    if (editingId) {
      setHabits(habits.map(h => h.id === editingId ? { ...h, ...form } : h));
    } else {
      setHabits([...habits, { ...form, id: Date.now(), logs: [] }]);
    }
    setShowModal(false);
  }

  function toggleLog(id, dateStr) {
    setHabits(habits.map(h => {
      if (h.id !== id) return h;
      const logs = h.logs.includes(dateStr)
        ? h.logs.filter(d => d !== dateStr)
        : [...h.logs, dateStr];
      return { ...h, logs };
    }));
  }

  function deleteHabit(id) {
    setHabits(habits.filter(h => h.id !== id));
    setShowDeleteConfirm(null);
  }

  return (
    <div style={{ padding: '32px 24px 24px', minHeight: '100vh', backgroundColor: 'var(--bg)' }}>

      {/* Header */}
      <p style={{ color: 'var(--text-secondary)', fontSize: '13px', letterSpacing: '0.1em' }}>TRACK</p>
      <h1 style={{ fontSize: '28px', fontWeight: '300', marginTop: '4px', marginBottom: '24px' }}>Habits</h1>

      {/* Filter pills */}
      <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', marginBottom: '24px', paddingBottom: '4px' }}>
        {['All', ...FREQUENCIES].map(f => (
          <button key={f} onClick={() => setFilter(f)} style={{
            flexShrink: 0,
            padding: '6px 14px', borderRadius: '20px', border: '1px solid',
            borderColor: filter === f ? 'var(--accent)' : 'var(--border)',
            backgroundColor: filter === f ? 'var(--accent)' : 'transparent',
            color: filter === f ? 'var(--white)' : 'var(--text-secondary)',
            fontSize: '12px', fontFamily: 'Jost, sans-serif',
            fontWeight: '500', letterSpacing: '0.05em', cursor: 'pointer',
          }}>{f.toUpperCase()}</button>
        ))}
      </div>

      {/* Habit list */}
      {filtered.length === 0 ? (
        <div style={{ textAlign: 'center', marginTop: '60px', color: 'var(--text-secondary)' }}>
          <p style={{ fontSize: '32px', marginBottom: '12px' }}>◎</p>
          <p style={{ fontSize: '14px' }}>No habits yet</p>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          {filtered.map(habit => {
            const streak = calcStreak(habit.logs);
            const rate = calcCompletionRate(habit.logs, habit.frequency);
            const doneToday = habit.logs.includes(todayStr);

            return (
              <div key={habit.id} style={{
                backgroundColor: 'var(--white)', borderRadius: '16px',
                padding: '16px', borderLeft: `4px solid ${habit.color}`,
              }}>
                {/* Top row */}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '12px' }}>
                <div style={{ flex: 1 }} onClick={() => setShowStats(showStats === habit.id ? null : habit.id)}>
                    <p style={{ fontSize: '15px', fontWeight: '500', marginBottom: '2px' }}>{habit.title}</p>
                    <p style={{ fontSize: '11px', color: 'var(--text-secondary)', letterSpacing: '0.05em' }}>
                      {habit.frequency.toUpperCase()}
                    </p>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    {/* Done today button */}
                    <button onClick={() => toggleLog(habit.id, todayStr)} style={{
                      padding: '6px 14px', borderRadius: '20px', border: '1.5px solid',
                      borderColor: doneToday ? habit.color : 'var(--border)',
                      backgroundColor: doneToday ? habit.color : 'transparent',
                      color: doneToday ? 'var(--white)' : 'var(--text-secondary)',
                      fontFamily: 'Jost, sans-serif', fontSize: '12px', fontWeight: '500',
                      cursor: 'pointer', whiteSpace: 'nowrap',
                    }}>{doneToday ? 'Done ✓' : 'Mark done'}</button>
                    <button onClick={() => setShowDeleteConfirm(habit.id)} style={{
                      background: 'none', border: 'none', color: 'var(--border)',
                      fontSize: '16px', cursor: 'pointer', padding: '0',
                    }}>✕</button>
                  </div>
                </div>

                {/* Weekly grid */}
                <div style={{ display: 'flex', gap: '4px', marginBottom: '12px' }}>
                  {weekDates.map((date, i) => {
                    const done = habit.logs.includes(date);
                    const isToday = date === todayStr;
                    return (
                      <div key={date} onClick={() => toggleLog(habit.id, date)}
                        style={{
                          flex: 1, aspectRatio: '1', borderRadius: '6px',
                          backgroundColor: done ? habit.color : 'var(--surface)',
                          display: 'flex', flexDirection: 'column',
                          alignItems: 'center', justifyContent: 'center',
                          cursor: 'pointer', border: isToday ? `1.5px solid ${habit.color}` : '1.5px solid transparent',
                          gap: '2px',
                        }}>
                        <span style={{ fontSize: '9px', color: done ? 'rgba(255,255,255,0.8)' : 'var(--text-secondary)', fontWeight: '500' }}>
                          {DAYS[i]}
                        </span>
                      </div>
                    );
                  })}
                </div>

                {/* Progress bar */}
                <div style={{ marginBottom: '10px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px' }}>
                    <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>Completion rate</span>
                    <span style={{ fontSize: '11px', color: habit.color, fontWeight: '600' }}>{rate}%</span>
                  </div>
                  <div style={{ height: '4px', backgroundColor: 'var(--surface)', borderRadius: '2px' }}>
                    <div style={{
                      height: '100%', borderRadius: '2px',
                      backgroundColor: habit.color,
                      width: `${rate}%`, transition: 'width 0.3s',
                    }} />
                  </div>
                </div>

                {/* Streak */}
                <div style={{ display: 'flex', gap: '16px' }}>
                  <div>
                    <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>Current streak </span>
                    <span style={{ fontSize: '13px', fontWeight: '600', color: habit.color }}>{streak.current} days</span>
                  </div>
                  <div>
                    <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>Best </span>
                    <span style={{ fontSize: '13px', fontWeight: '600', color: 'var(--text-primary)' }}>{streak.best} days</span>
                  </div>
                  <div>
                    <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>Total </span>
                    <span style={{ fontSize: '13px', fontWeight: '600', color: 'var(--text-primary)' }}>{(habit.logs || []).length} days</span>
                  </div>
                </div>

                {/* Stats expansion */}
                {showStats === habit.id && (
                  <div style={{ marginTop: '12px', paddingTop: '12px', borderTop: '1px solid var(--surface)' }}>
                    <p style={{ fontSize: '11px', letterSpacing: '0.08em', color: 'var(--text-secondary)', marginBottom: '10px' }}>MONTHLY OVERVIEW</p>
                    <div style={{ display: 'flex', gap: '3px', flexWrap: 'wrap' }}>
                      {Array.from({ length: 30 }, (_, i) => {
                        const d = new Date();
                        d.setDate(d.getDate() - (29 - i));
                        const dateStr = d.toISOString().split('T')[0];
                        const done = (habit.logs || []).includes(dateStr);
                        const isToday = dateStr === todayStr;
                        return (
                          <div key={dateStr} style={{
                            width: '8px', height: '8px', borderRadius: '2px',
                            backgroundColor: done ? habit.color : 'var(--surface)',
                            border: isToday ? `1px solid ${habit.color}` : 'none',
                          }} />
                        );
                      })}
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '10px' }}>
                      <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>30 days ago</span>
                      <span style={{ fontSize: '11px', color: 'var(--text-secondary)' }}>Today</span>
                    </div>
                    <button onClick={() => openEdit(habit)} style={{
                      marginTop: '12px', width: '100%', padding: '8px',
                      borderRadius: '8px', border: '1px solid var(--border)',
                      backgroundColor: 'transparent', fontFamily: 'Jost, sans-serif',
                      fontSize: '12px', color: 'var(--text-secondary)', cursor: 'pointer',
                    }}>Edit habit</button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Floating action button */}
      <button onClick={openCreate} style={{
        position: 'fixed', bottom: 'calc(var(--nav-height) + 20px)', right: '24px',
        width: '52px', height: '52px', borderRadius: '50%',
        backgroundColor: 'var(--accent)', color: 'var(--white)',
        fontSize: '26px', border: 'none', cursor: 'pointer',
        boxShadow: '0 4px 16px rgba(160, 133, 108, 0.4)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
      }}>+</button>

      {/* Delete confirmation */}
      {showDeleteConfirm && (
        <div style={{
          position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)',
          display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200,
        }}>
          <div style={{
            backgroundColor: 'var(--white)', borderRadius: '20px 20px 0 0',
            padding: '28px 24px', width: '100%', maxWidth: '390px',
          }}>
            <h3 style={{ fontWeight: '500', marginBottom: '8px' }}>Delete habit?</h3>
            <p style={{ color: 'var(--text-secondary)', fontSize: '14px', marginBottom: '24px' }}>All your progress will be lost.</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowDeleteConfirm(null)} style={{
                flex: 1, padding: '14px', borderRadius: '12px',
                border: '1px solid var(--border)', backgroundColor: 'transparent',
                fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
              }}>Cancel</button>
              <button onClick={() => deleteHabit(showDeleteConfirm)} style={{
                flex: 1, padding: '14px', borderRadius: '12px', border: 'none',
                backgroundColor: 'var(--danger)', color: 'var(--white)',
                fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
              }}>Delete</button>
            </div>
          </div>
        </div>
      )}

      {/* Create / Edit modal */}
      {showModal && (
        <div style={{
          position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.4)',
          display: 'flex', alignItems: 'flex-end', justifyContent: 'center', zIndex: 200,
        }}>
          <div style={{
            backgroundColor: 'var(--bg)', borderRadius: '20px 20px 0 0',
            padding: '28px 24px', width: '100%', maxWidth: '390px',
            maxHeight: '90vh', overflowY: 'auto',
          }}>
            <h3 style={{ fontWeight: '500', marginBottom: '24px', fontSize: '18px' }}>
              {editingId ? 'Edit Habit' : 'New Habit'}
            </h3>

            {/* Title */}
            <label style={labelStyle}>HABIT NAME</label>
            <input
              value={form.title}
              onChange={e => setForm({ ...form, title: e.target.value })}
              placeholder="e.g. Morning walk, Read, Meditate"
              style={inputStyle}
            />

            {/* Start date */}
            <label style={labelStyle}>START DATE</label>
            <input
              type="date"
              value={form.startDate}
              onChange={e => setForm({ ...form, startDate: e.target.value })}
              style={inputStyle}
            />
            {/* Frequency */}
            <label style={labelStyle}>FREQUENCY</label>
            <div style={{ display: 'flex', gap: '8px', marginBottom: '20px' }}>
              {FREQUENCIES.map(f => (
                <button key={f} onClick={() => setForm({ ...form, frequency: f })} style={{
                  flex: 1, padding: '10px 4px', borderRadius: '10px', border: '1.5px solid',
                  borderColor: form.frequency === f ? 'var(--accent)' : 'var(--border)',
                  backgroundColor: form.frequency === f ? 'var(--accent)' : 'transparent',
                  color: form.frequency === f ? 'var(--white)' : 'var(--text-secondary)',
                  fontFamily: 'Jost, sans-serif', fontSize: '11px', fontWeight: '500',
                  cursor: 'pointer',
                }}>{f}</button>
              ))}
            </div>

            {/* Color */}
            <label style={labelStyle}>COLOUR</label>
            <div style={{ display: 'flex', gap: '10px', marginBottom: '28px' }}>
              {COLORS.map(c => (
                <button key={c} onClick={() => setForm({ ...form, color: c })} style={{
                  width: '32px', height: '32px', borderRadius: '50%',
                  backgroundColor: c, border: form.color === c ? '3px solid var(--text-primary)' : '3px solid transparent',
                  cursor: 'pointer', outline: 'none',
                }} />
              ))}
            </div>

            {/* Buttons */}
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={() => setShowModal(false)} style={{
                flex: 1, padding: '14px', borderRadius: '12px',
                border: '1px solid var(--border)', backgroundColor: 'transparent',
                fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
              }}>Cancel</button>
              <button onClick={saveHabit} style={{
                flex: 1, padding: '14px', borderRadius: '12px',
                border: 'none', backgroundColor: 'var(--accent)', color: 'var(--white)',
                fontFamily: 'Jost, sans-serif', fontSize: '14px', cursor: 'pointer',
              }}>{editingId ? 'Save Changes' : 'Add Habit'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = {
  display: 'block', fontSize: '11px', letterSpacing: '0.1em',
  color: 'var(--text-secondary)', marginBottom: '8px', fontWeight: '500',
};

const inputStyle = {
  width: '100%', padding: '12px 14px', borderRadius: '10px',
  border: '1px solid var(--border)', backgroundColor: 'var(--white)',
  fontFamily: 'Jost, sans-serif', fontSize: '14px',
  color: 'var(--text-primary)', marginBottom: '20px', outline: 'none',
};

export default Habits;